files.content:
html,
body {
  box-sizing: border-box;
  height: 100%;
  font-family: Inter, sans-serif;
}

body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 1024px;
  margin: 0;
  padding: 100px;
  background-color: gold;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
}

header h1 {
  margin: 0;
  font-weight: normal;
  font-size: 40px;
}

header img {
  height: 120px;
}

.book {
  display: flex;
  gap: 20px;
}

.menu {
  width: 300px;
  border-radius: 10px;
  padding: 20px;
  background-color: rgb(0 0 0 / 0.8);
}

.menu ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.menu ul li {
  margin-bottom: 20px;
}

.menu ul li a {
  color: #fff;
  text-decoration: none;
}

.content {
  box-sizing: border-box;
  width: calc(100% - 300px);
  max-height: 400px;
  border-radius: 10px;
  padding: 20px 40px;
  overflow: scroll;
  scroll-behavior: smooth;
  line-height: 1.35;
  background-color: #fff;
}
